);
CREATE INDEX IF NOT EXISTS idx_agent_seats_tenant_status ON agent_seats(tenant_id, status, last_heartbeat_at DESC);

CREATE TABLE IF NOT EXISTS outbound_tasks (
  id TEXT PRIMARY KEY,
