  strategy TEXT NOT NULL DEFAULT '{}',
  attempt_count INTEGER NOT NULL DEFAULT 0,
  max_attempts INTEGER NOT NULL DEFAULT 3,
  priority INTEGER NOT NULL DEFAULT 5,
  scheduled_at TEXT,
  started_at TEXT,
  completed_at TEXT,
  result TEXT NOT NULL DEFAULT '{}',
  call_session_id TEXT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_outbound_tasks_pick ON outbound_tasks(tenant_id, status, priority DESC, created_at ASC);
CREATE INDEX IF NOT EXISTS idx_outbound_tasks_phone ON outbound_tasks(tenant_id, phone_number, created_at DESC);

-- ===== RustDesk Remote Desktop Gateway =====

CREATE TABLE IF NOT EXISTS rustdesk_devices (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  business_ref_type TEXT NOT NULL,
  business_ref_id TEXT NOT NULL,
  rustdesk_id TEXT NOT NULL,
  display_name TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  runtime_status TEXT NOT NULL DEFAULT 'unknown' CHECK (runtime_status IN ('unknown', 'online', 'offline')),
  metadata TEXT NOT NULL DEFAULT '{}',
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  deactivated_at TIMESTAMPTZ,
  last_seen_at TIMESTAMPTZ,
  last_seen_actor TEXT NOT NULL DEFAULT ''
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_rustdesk_devices_tenant_rustdesk
  ON rustdesk_devices(tenant_id, rustdesk_id)
  WHERE deactivated_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_rustdesk_devices_business_ref
  ON rustdesk_devices(tenant_id, business_ref_type, business_ref_id, created_at DESC)
  WHERE deactivated_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_rustdesk_devices_runtime_status
  ON rustdesk_devices(tenant_id, runtime_status, last_seen_at DESC)
  WHERE deactivated_at IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_rustdesk_devices_tenant_id
  ON rustdesk_devices(tenant_id, id);

CREATE TABLE IF NOT EXISTS rustdesk_access_policy_events (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,
  device_id TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('configured', 'revoked')),
  mode TEXT NOT NULL CHECK (mode IN ('attended_only', 'unattended_allowed')),
  allowed_scopes JSONB NOT NULL DEFAULT '[]'::jsonb
    CHECK (jsonb_typeof(allowed_scopes) = 'array')
    CHECK (allowed_scopes <@ '["view_screen","control_mouse_keyboard","record_screen","transfer_file","clipboard"]'::jsonb),
  business_ref_type TEXT NOT NULL,
  business_ref_id TEXT NOT NULL,
  approved_by TEXT NOT NULL,
  reason TEXT NOT NULL CHECK (char_length(btrim(reason)) BETWEEN 1 AND 1000),
  expires_at TIMESTAMPTZ,
  supersedes_id TEXT,
  version INTEGER NOT NULL CHECK (version > 0),
  idempotency_key TEXT NOT NULL CHECK (char_length(idempotency_key) BETWEEN 1 AND 200),
  request_hash TEXT NOT NULL CHECK (request_hash ~ '^[a-f0-9]{64}$'),
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (tenant_id, device_id, id),
  UNIQUE (tenant_id, device_id, version),
  UNIQUE (tenant_id, idempotency_key),
  FOREIGN KEY (tenant_id, device_id) REFERENCES rustdesk_devices(tenant_id, id) ON DELETE RESTRICT,
  FOREIGN KEY (tenant_id, device_id, supersedes_id)
    REFERENCES rustdesk_access_policy_events(tenant_id, device_id, id) ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS idx_rustdesk_access_policy_current
  ON rustdesk_access_policy_events(tenant_id, device_id, version DESC);

CREATE INDEX IF NOT EXISTS idx_rustdesk_access_policy_business_ref
  ON rustdesk_access_policy_events(tenant_id, business_ref_type, business_ref_id, created_at DESC);

CREATE OR REPLACE FUNCTION reject_rustdesk_access_policy_event_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'access policy history is immutable';
END;
$$;

DROP TRIGGER IF EXISTS rustdesk_access_policy_events_immutable
  ON rustdesk_access_policy_events;

CREATE TRIGGER rustdesk_access_policy_events_immutable
BEFORE UPDATE OR DELETE ON rustdesk_access_policy_events
FOR EACH ROW EXECUTE FUNCTION reject_rustdesk_access_policy_event_mutation();

CREATE TABLE IF NOT EXISTS rustdesk_gateway_sessions (
  external_id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL DEFAULT 'system',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'ended')),
  target_type TEXT NOT NULL DEFAULT 'device',
  target_id TEXT NOT NULL,
  target_display_name TEXT NOT NULL DEFAULT '',
  permissions TEXT NOT NULL DEFAULT '[]',
  actor_identity TEXT NOT NULL DEFAULT '',
  launch_url TEXT NOT NULL DEFAULT '',
  metadata TEXT NOT NULL DEFAULT '{}',
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  ended_at TIMESTAMPTZ,
  ended_by TEXT NOT NULL DEFAULT ''
);

CREATE INDEX IF NOT EXISTS idx_rustdesk_gateway_sessions_tenant_created
  ON rustdesk_gateway_sessions(tenant_id, created_at DESC);

CREATE TABLE IF NOT EXISTS rustdesk_gateway_events (
  id TEXT PRIMARY KEY,
  external_id TEXT NOT NULL REFERENCES rustdesk_gateway_sessions(external_id) ON DELETE CASCADE,
  tenant_id TEXT NOT NULL DEFAULT 'system',
  event_type TEXT NOT NULL,
  actor_identity TEXT NOT NULL DEFAULT '',
  target TEXT NOT NULL DEFAULT '',
  idempotency_key TEXT NOT NULL DEFAULT '',
  metadata TEXT NOT NULL DEFAULT '{}',
  occurred_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_rustdesk_gateway_events_session_time
  ON rustdesk_gateway_events(external_id, occurred_at ASC, created_at ASC);

CREATE INDEX IF NOT EXISTS idx_rustdesk_gateway_events_tenant_time
  ON rustdesk_gateway_events(tenant_id, occurred_at DESC);

CREATE UNIQUE INDEX IF NOT EXISTS idx_rustdesk_gateway_events_idempotency
  ON rustdesk_gateway_events(external_id, idempotency_key)
  WHERE idempotency_key <> '';

CREATE TABLE IF NOT EXISTS rustdesk_device_commands (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  device_id TEXT NOT NULL REFERENCES rustdesk_devices(id) ON DELETE CASCADE,
  external_id TEXT NOT NULL REFERENCES rustdesk_gateway_sessions(external_id) ON DELETE CASCADE,
  command_type TEXT NOT NULL DEFAULT 'disconnect_session'
    CHECK (command_type = 'disconnect_session'),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'claimed', 'succeeded', 'failed')),
  requested_by TEXT NOT NULL,
  requested_reason TEXT NOT NULL
    CHECK (requested_reason IN ('consent_revoked', 'remote_session_ended', 'tool_ended', 'gateway_ended')),
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  max_attempts INTEGER NOT NULL DEFAULT 3 CHECK (max_attempts > 0),
  claimed_by TEXT,
  claim_token_hash TEXT,
  lease_expires_at TIMESTAMPTZ,
  next_attempt_at TIMESTAMPTZ,
  execution_method TEXT
    CHECK (execution_method IS NULL OR execution_method IN ('session_adapter', 'service_restart')),
  exit_code INTEGER,
  duration_ms INTEGER CHECK (duration_ms IS NULL OR duration_ms >= 0),
  stdout_bytes INTEGER CHECK (stdout_bytes IS NULL OR stdout_bytes >= 0),
  stderr_bytes INTEGER CHECK (stderr_bytes IS NULL OR stderr_bytes >= 0),
  stdout_sha256 TEXT,
  stderr_sha256 TEXT,
  result_metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  requested_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (tenant_id, external_id, command_type)
);

CREATE INDEX IF NOT EXISTS idx_rustdesk_device_commands_claim
  ON rustdesk_device_commands(tenant_id, device_id, status, next_attempt_at, requested_at);

CREATE TABLE IF NOT EXISTS rustdesk_control_locks (
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  external_id TEXT NOT NULL REFERENCES rustdesk_gateway_sessions(external_id) ON DELETE CASCADE,
  owner_identity TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('owned', 'transferring', 'released', 'expired')),
  lease_expires_at TIMESTAMPTZ NOT NULL,
  version INTEGER NOT NULL CHECK (version > 0),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (tenant_id, external_id)
);

CREATE INDEX IF NOT EXISTS idx_rustdesk_control_locks_expiry
  ON rustdesk_control_locks(tenant_id, status, lease_expires_at);

CREATE TABLE IF NOT EXISTS rustdesk_secondary_confirmations (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
  external_id TEXT NOT NULL REFERENCES rustdesk_gateway_sessions(external_id) ON DELETE CASCADE,
  actor_identity TEXT NOT NULL,
  operation TEXT NOT NULL CHECK (operation IN (
    'control_mouse_keyboard', 'transfer_file', 'clipboard', 'unattended_launch', 'control_transfer'
  )),
  expires_at TIMESTAMPTZ NOT NULL,
  consumed_at TIMESTAMPTZ,
  consumed_by_event_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_rustdesk_secondary_confirmations_lookup
  ON rustdesk_secondary_confirmations(tenant_id, external_id, actor_identity, operation, expires_at DESC);

CREATE TABLE IF NOT EXISTS rustdesk_control_events (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,
  external_id TEXT NOT NULL REFERENCES rustdesk_gateway_sessions(external_id) ON DELETE CASCADE,
  event_type TEXT NOT NULL CHECK (event_type IN (
    'acquired', 'heartbeat', 'released', 'expired', 'transfer_started', 'transferred', 'operation_confirmed'
  )),
  actor_identity TEXT NOT NULL,
  previous_owner_identity TEXT,
  owner_identity TEXT,
  operation TEXT,
  lock_version INTEGER NOT NULL CHECK (lock_version >= 0),
  confirmation_id TEXT REFERENCES rustdesk_secondary_confirmations(id) ON DELETE RESTRICT,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_rustdesk_control_events_session
  ON rustdesk_control_events(tenant_id, external_id, created_at ASC, id ASC);

CREATE OR REPLACE FUNCTION reject_rustdesk_control_event_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'RustDesk control history is immutable';
END;
$$;

DROP TRIGGER IF EXISTS rustdesk_control_events_immutable ON rustdesk_control_events;
CREATE TRIGGER rustdesk_control_events_immutable
BEFORE UPDATE OR DELETE ON rustdesk_control_events
FOR EACH ROW EXECUTE FUNCTION reject_rustdesk_control_event_mutation();


